using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Square.Models.Enums;

namespace Square.Models;

/// <summary>
/// Represents the payment details of a card to be used for payments. These
/// details are determined by the payment token generated by Web Payments SDK.
/// </summary>
public record Card
{
    /// <summary>
    /// Unique ID for this card. Generated by Square.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("id")]
    [MaxLength(64)]
    public string? Id { get; init; }

    /// <summary>
    /// Indicates a card's brand, such as <c>VISA</c> or <c>MASTERCARD</c>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("card_brand")]
    public CardBrand? CardBrand { get; init; }

    /// <summary>
    /// The last 4 digits of the card number.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("last_4")]
    [MaxLength(4)]
    public string? Last4 { get; init; }

    /// <summary>
    /// The expiration month of the associated card as an integer between 1 and 12.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("exp_month")]
    public long? ExpMonth { get; init; }

    /// <summary>
    /// The four-digit year of the card's expiration date.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("exp_year")]
    public long? ExpYear { get; init; }

    /// <summary>
    /// The name of the cardholder.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cardholder_name")]
    [MaxLength(96)]
    public string? CardholderName { get; init; }

    /// <summary>
    /// Represents a postal address in a country.
    /// For more information, see <see href="https://developer.squareup.com/docs/build-basics/working-with-addresses">Working with Addresses</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("billing_address")]
    public Address? BillingAddress { get; init; }

    /// <summary>
    /// Intended as a Square-assigned identifier, based
    /// on the card number, to identify the card across multiple locations within a
    /// single application.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("fingerprint")]
    [MaxLength(255)]
    public string? Fingerprint { get; init; }

    /// <summary>
    /// <b>Required</b> The ID of a <see href="entity:Customer">customer</see> to be associated with the card.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("customer_id")]
    public string? CustomerId { get; init; }

    /// <summary>
    /// The ID of the merchant associated with the card.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("merchant_id")]
    public string? MerchantId { get; init; }

    /// <summary>
    /// An optional user-defined reference ID that associates this card with
    /// another entity in an external system. For example, a customer ID from an
    /// external customer management system.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("reference_id")]
    [MaxLength(128)]
    public string? ReferenceId { get; init; }

    /// <summary>
    /// Indicates whether or not a card can be used for payments.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("enabled")]
    public bool? Enabled { get; init; }

    /// <summary>
    /// Indicates a card's type, such as <c>CREDIT</c> or <c>DEBIT</c>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("card_type")]
    public CardType? CardType { get; init; }

    /// <summary>
    /// Indicates a card's prepaid type, such as <c>NOT_PREPAID</c> or <c>PREPAID</c>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("prepaid_type")]
    public CardPrepaidType? PrepaidType { get; init; }

    /// <summary>
    /// The first six digits of the card number, known as the Bank Identification Number (BIN). Only the Payments API
    /// returns this field.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("bin")]
    [MaxLength(6)]
    public string? Bin { get; init; }

    /// <summary>
    /// Timestamp for when the card object was created on Square’s servers. In RFC 3339 format, e.g., "2016-09-04T23:59:33.123Z".
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("created_at")]
    public string? CreatedAt { get; init; }

    /// <summary>
    /// Timestamp for when the card object was disabled on Square’s servers. In RFC 3339 format, e.g., "2016-09-04T23:59:33.123Z".
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("disabled_at")]
    public string? DisabledAt { get; init; }

    /// <summary>
    /// Current version number of the card. Increments with each card update. Requests to update an
    /// existing Card object will be rejected unless the version in the request matches the current
    /// version for the Card.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("version")]
    public long? Version { get; init; }

    /// <summary>
    /// Indicates the brand for a co-branded card.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("card_co_brand")]
    public CardCoBrand? CardCoBrand { get; init; }

    /// <summary>
    /// Indicates the type of issuer alert for a <see href="entity:Card">card on file</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("issuer_alert")]
    public CardIssuerAlert? IssuerAlert { get; init; }

    /// <summary>
    /// The timestamp of when the current issuer alert was received and processed, in
    /// RFC 3339 format.
    /// <para>
    /// This field is present only if there's an active issuer alert.
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("issuer_alert_at")]
    public string? IssuerAlertAt { get; init; }

    /// <summary>
    /// Indicates whether the card is linked to a Health Savings Account (HSA) or Flexible
    /// Spending Account (FSA), based on the card BIN.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("hsa_fsa")]
    public bool? HsaFsa { get; init; }
}
